# ================================================================ validação
LIVROS_PERMITIDOS = set(range(19, 39)) | {42, 43}
ES_PROIBIDO = re.compile(r"\b(tú|tienes|puedes|tu)\b", re.IGNORECASE)
PT_PROIBIDO = re.compile(r"\b(tu|teu|tua|teus|tuas|ti|contigo)\b", re.IGNORECASE)  # só em r/a (leitor = "você")
REF = re.compile(r"^(\d+)\.(\d+)\.(\d+)(?:-(\d+))?$")

def palavras(s):
    return len(re.findall(r"[^\s—–-]+", s.replace("—", " ")))

def carregar(nome):
    with open(os.path.join(RAIZ, "app", "biblia", nome), encoding="utf-8") as f:
        return json.load(f)

def main():
    pt, es = carregar("pt-livre.json"), carregar("es-rv1909.json")
    erros, vistos = [], set()
    total = DIA_FINAL - DIA_INICIAL + 1
    if len(D) != total:
        erros.append(f"esperados {total} devocionais, há {len(D)}")
    for i, d in enumerate(D):
        dia = DIA_INICIAL + i
        e = lambda m: erros.append(f"dia {dia} ({d.get('v')}): {m}")
        if set(d) != {"t", "v", "r", "a", "o"}:
            e(f"chaves {sorted(d)}")
        for k in ("t", "r", "a", "o"):
            if not (isinstance(d[k], list) and len(d[k]) == 2 and all(isinstance(x, str) and x.strip() for x in d[k])):
                e(f"campo {k} deve ser [ES, PT]")
        m = REF.match(d["v"])
        if not m:
            e("formato de referência inválido"); continue
        b, c, v1 = int(m[1]), int(m[2]), int(m[3])
        v2 = int(m[4]) if m[4] else v1
        if b not in LIVROS_PERMITIDOS:
            e(f"livro {b} fora dos livros desta parte")
        if not (v1 <= v2 <= v1 + 2):
            e("intervalo deve ter de 1 a 3 versículos")
        for nome, B in (("pt", pt), ("es", es)):
            try:
                cap = B[b][c - 1]
                if c < 1 or v1 < 1 or v2 > len(cap) or not all(cap[x - 1].strip() for x in range(v1, v2 + 1)):
                    raise IndexError
            except (IndexError, TypeError):
                e(f"referência inexistente em {nome}")
        for x in range(v1, v2 + 1):
            if (b, c, x) in vistos:
                e(f"versículo {b}.{c}.{x} repetido")
            vistos.add((b, c, x))
        for li, lang in enumerate(("ES", "PT")):
            n = len(d["t"][li].split())
            if not 2 <= n <= 6: e(f"título {lang} com {n} palavras")
            n = palavras(d["r"][li])
            if not 90 <= n <= 140: e(f"reflexão {lang} com {n} palavras")
            n = palavras(d["o"][li])
            if not 30 <= n <= 60: e(f"oração {lang} com {n} palavras")
            if d["a"][li].count(".") > 1 or not d["a"][li].endswith("."):
                e(f"'para hoje' {lang} deve ser uma frase")
        if not d["o"][0].endswith("En el nombre de Jesús, amén."): e("oração ES sem fecho")
        if not d["o"][1].endswith("Em nome de Jesus, amém."): e("oração PT sem fecho")
        for k in ("t", "r", "a", "o"):
            mm = ES_PROIBIDO.search(d[k][0])
            if mm: e(f"ES {k} contém '{mm[0]}' (usar usted)")
        for k in ("r", "a"):
            mm = PT_PROIBIDO.search(d[k][1])
            if mm: e(f"PT {k} contém '{mm[0]}' (usar você)")
        for k in ("t", "r", "a", "o"):
            for x in d[k]:
                if re.search(r"[\U0001F300-\U0001FAFF☀-➿]", x): e("emoji")
    if erros:
        print("\n".join(erros)); print(f"{len(erros)} erro(s)."); sys.exit(1)
    saida = os.path.join(AQUI, "devocional-4.json")
    with open(saida, "w", encoding="utf-8") as f:
        json.dump(D, f, ensure_ascii=False, separators=(",", ":"))
    print(f"OK: {len(D)} devocionais (dias {DIA_INICIAL}-{DIA_FINAL}) -> {os.path.relpath(saida, RAIZ)}")

if __name__ == "__main__":
    main()
